starter:
def check_basket(prices):
    # for ... else: break when you find a price over 20
    pass

solution:
def check_basket(prices):
    for price in prices:
        if price > 20:
            print('Expensive:', price)
            break
    else:
        print('Everything is cheap')

starter:
def find_book(shelf, title):
    # while i < len(shelf): break when found; else: return -1
    pass

solution:
def find_book(shelf, title):
    i = 0
    while i < len(shelf):
        if shelf[i] == title:
            break
        i += 1
    else:
        return -1
    return i
